<script>
  const DATA = {data_json};

  function $(id) {{ return document.getElementById(id); }}

  function niceMax(x) {{
    if (!isFinite(x) || x <= 0) return 1;
    const pow = Math.pow(10, Math.floor(Math.log10(x)));
    const n = x / pow;
    const m = n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10;
    return m * pow;
  }}

  function barChart(svg, items, opts) {{
    const W = svg.viewBox.baseVal.width, H = svg.viewBox.baseVal.height;
    const pad = {{l: 130, r: 20, t: 18, b: 40}};
    const innerW = W - pad.l - pad.r;
    const innerH = H - pad.t - pad.b;

    const maxV = Math.max(0, ...items.map(d => d.value || 0));
    const yMax = niceMax(maxV * 1.05);

    while (svg.firstChild) svg.removeChild(svg.firstChild);

    const gridN = 5;
    for (let i=0;i<=gridN;i++) {{
      const y = pad.t + innerH - (i/gridN)*innerH;
      const line = document.createElementNS('http://www.w3.org/2000/svg','line');
      line.setAttribute('x1', pad.l);
      line.setAttribute('x2', pad.l + innerW);
      line.setAttribute('y1', y);
      line.setAttribute('y2', y);
      line.setAttribute('stroke', 'rgba(31,43,69,0.9)');
      line.setAttribute('stroke-width','1');
      svg.appendChild(line);

      const txt = document.createElementNS('http://www.w3.org/2000/svg','text');
      txt.setAttribute('x', pad.l - 8);
      txt.setAttribute('y', y + 4);
      txt.setAttribute('text-anchor','end');
      txt.setAttribute('fill','rgba(159,176,208,0.95)');
      txt.setAttribute('font-size','11');
      const v = (i/gridN)*yMax;
      txt.textContent = opts.tickFmt ? opts.tickFmt(v) : Math.round(v).toString();
      svg.appendChild(txt);
    }}

    const n = items.length;
    const barH = innerH / n;
    const barPad = 6;

    items.forEach((d, idx) => {{
      const y0 = pad.t + idx*barH + barPad;
      const h = barH - barPad*2;
      const v = d.value || 0;
      const w = (v / yMax) * innerW;

      const label = document.createElementNS('http://www.w3.org/2000/svg','text');
      label.setAttribute('x', pad.l - 10);
      label.setAttribute('y', y0 + h/2 + 4);
      label.setAttribute('text-anchor','end');
      label.setAttribute('fill','#eaf0ff');
      label.setAttribute('font-size','12');
      label.textContent = d.label;
      svg.appendChild(label);

      const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
      rect.setAttribute('x', pad.l);
      rect.setAttribute('y', y0);
      rect.setAttribute('width', Math.max(0,w));
      rect.setAttribute('height', h);
      rect.setAttribute('rx', 6);
      rect.setAttribute('fill', d.color || 'rgba(77,163,255,0.9)');
      rect.setAttribute('stroke', 'rgba(32,48,83,0.8)');
      rect.setAttribute('stroke-width','1');
      svg.appendChild(rect);

      const val = document.createElementNS('http://www.w3.org/2000/svg','text');
      val.setAttribute('x', pad.l + Math.max(0,w) + 8);
      val.setAttribute('y', y0 + h/2 + 4);
      val.setAttribute('fill','rgba(234,240,255,0.95)');
      val.setAttribute('font-size','12');
      val.setAttribute('font-family','ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace');
      val.textContent = (opts.valueFmt ? opts.valueFmt(v, d) : v.toString()) + (d.note ? `  (${d.note})` : '');
      svg.appendChild(val);
    }});
  }}

  function stacked100(svg, rows, categories, opts) {{
    const W = svg.viewBox.baseVal.width, H = svg.viewBox.baseVal.height;
    const pad = {{l: 120, r: 20, t: 18, b: 20}};
    const innerW = W - pad.l - pad.r;
    const innerH = H - pad.t - pad.b;

    while (svg.firstChild) svg.removeChild(svg.firstChild);

    const n = rows.length;
    const rowH = innerH / n;
    const barPad = 6;

    for (let p=0;p<=100;p+=20) {{
      const x = pad.l + (p/100)*innerW;
      const line = document.createElementNS('http://www.w3.org/2000/svg','line');
      line.setAttribute('x1', x);
      line.setAttribute('x2', x);
      line.setAttribute('y1', pad.t);
      line.setAttribute('y2', pad.t+innerH);
      line.setAttribute('stroke', 'rgba(31,43,69,0.7)');
      line.setAttribute('stroke-width','1');
      svg.appendChild(line);

      const txt = document.createElementNS('http://www.w3.org/2000/svg','text');
      txt.setAttribute('x', x);
      txt.setAttribute('y', pad.t+innerH+16);
      txt.setAttribute('text-anchor','middle');
      txt.setAttribute('fill','rgba(159,176,208,0.95)');
      txt.setAttribute('font-size','11');
      txt.textContent = p + '%';
      svg.appendChild(txt);
    }}

    rows.forEach((r, idx) => {{
      const y0 = pad.t + idx*rowH + barPad;
      const h = rowH - barPad*2;

      const label = document.createElementNS('http://www.w3.org/2000/svg','text');
      label.setAttribute('x', pad.l - 10);
      label.setAttribute('y', y0 + h/2 + 4);
      label.setAttribute('text-anchor','end');
      label.setAttribute('fill','#eaf0ff');
      label.setAttribute('font-size','12');
      label.textContent = r.label;
      svg.appendChild(label);

      let acc = 0;
      categories.forEach(cat => {{
        const v = r.values[cat] || 0;
        const x = pad.l + (acc/100)*innerW;
        const w = (v/100)*innerW;
        const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
        rect.setAttribute('x', x);
        rect.setAttribute('y', y0);
        rect.setAttribute('width', Math.max(0,w));
        rect.setAttribute('height', h);
        rect.setAttribute('fill', (opts.colors && opts.colors[cat]) || 'rgba(77,163,255,0.9)');
        rect.setAttribute('stroke', 'rgba(0,0,0,0)');
        svg.appendChild(rect);
        acc += v;
      }});

      const outline = document.createElementNS('http://www.w3.org/2000/svg','rect');
      outline.setAttribute('x', pad.l);
      outline.setAttribute('y', y0);
      outline.setAttribute('width', innerW);
      outline.setAttribute('height', h);
      outline.setAttribute('rx', 6);
      outline.setAttribute('fill', 'none');
      outline.setAttribute('stroke', 'rgba(32,48,83,0.8)');
      outline.setAttribute('stroke-width','1');
      svg.appendChild(outline);
    }});
  }}

  const perCity = DATA.per_city.slice();

  const listingsItems = perCity.slice().sort((a,b)=>b.listings-a.listings)
    .map(d=>({{label:d.city, value:d.listings, note: null, color:'rgba(77,163,255,0.9)'}}));
  barChart($('chart_listings'), listingsItems, {{ tickFmt:(v)=>Math.round(v).toLocaleString(), valueFmt:(v)=>Math.round(v).toLocaleString() }});

  const mixRows = [];
  const mix = DATA.room_mix;
  const cats = ['Entire home/apt','Private room','Hotel room','Shared room'];
  const colors = {{
    'Entire home/apt':'#4da3ff',
    'Private room':'#7c5cff',
    'Hotel room':'#3ddc97',
    'Shared room':'#ffcc66'
  }};
  const cities = [...new Set(mix.map(d=>d.city))];
  cities.sort((a,b)=>{{
    const la = (perCity.find(x=>x.city===a) || {{}}).listings || 0;
