    .legend{{ display:flex; gap:10px; flex-wrap:wrap; margin-top:10px; color:var(--muted); font-size:12px; }}
    .legend .swatch{{ width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; }}

    .tbl{{ width:100%; border-collapse:separate; border-spacing:0; margin-top:10px; overflow:hidden; border-radius:12px; border:1px solid var(--border); }}
    .tbl th{{ text-align:left; font-size:12px; color:var(--muted); font-weight:600; padding:10px 10px; background:rgba(255,255,255,0.03); border-bottom:1px solid var(--border); position:sticky; top:0; }}
    .tbl td{{ padding:10px 10px; border-bottom:1px solid rgba(32,48,83,0.6); vertical-align:top; }}
    .tbl tr:last-child td{{ border-bottom:none; }}
    .tbl td:nth-child(1){{ font-weight:650; }}

    .callout{{ background:rgba(77,163,255,0.08); border:1px solid rgba(77,163,255,0.35); border-radius:12px; padding:12px; color:var(--text); }}
    .callout strong{{ color:#cfe6ff; }}

    ol.takeaways{{ margin:8px 0 0 22px; }}
    ol.takeaways li{{ margin:10px 0; color:var(--text); line-height:1.5; }}
    .muted{{ color:var(--muted); }}

    footer{{ margin-top:18px; color:var(--muted); font-size:12px; }}
    code{{ font-family:var(--mono); font-size:12px; }}
  </style>
</head>
<body>
<div class='wrap'>
  <header>
    <div>
      <h1>{title}</h1>
      <div class='sub'>{one_liner}</div>
      <div class='meta'>
        <span class='pill'>Dataset scrape_date: <strong>{scrape_date}</strong></span>
        <span class='pill'>Rows analyzed: <strong>{rows_count}</strong></span>
        <span class='pill'>Cities present: <strong>{cities_n}</strong> / 10</span>
        <span class='pill'>Overall missing price: <strong>{missing_price_pct:.1f}%</strong></span>
      </div>
    </div>
  </header>

  <div class='grid'>
    <section class='card'>
      <h2>Executive Key Takeaways</h2>
      <ol class='takeaways'>{kt_html}</ol>
      <p class='muted'>All figures are computed strictly from <code>benchmark/data.csv</code>. Where metrics are unavailable (e.g., missing prices), the report flags the gap explicitly.</p>
    </section>

    <section class='card' id='market-overview'>
      <h2>Global Market Overview</h2>
      <p>This section establishes the relative market scale and composition (listings, room-type mix) across cities present in the dataset.</p>
      <div class='row2' style='margin-top:10px;'>
        <div class='span7'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Listings by city (count)</h3>
          <svg id='chart_listings' class='chart' viewBox='0 0 900 360' role='img' aria-label='Listings by city'></svg>
        </div>
        <div class='span5'>
          <div class='callout'>
            <strong>Coverage note:</strong> The dataset includes {cities_present}.
            {missing_note}
          </div>
          <h3 style='margin:14px 0 8px; font-size:14px; color:var(--muted);'>Room-type mix (share of listings)</h3>
          <svg id='chart_room_mix' class='chart' viewBox='0 0 520 360' role='img' aria-label='Room-type mix by city'></svg>
        </div>
      </div>
      <h3 style='margin:14px 0 8px; font-size:14px; color:var(--muted);'>City KPI snapshot</h3>
      {table_html}
    </section>

    <section class='card' id='pricing-analysis'>
      <h2>Pricing Dynamics Across Cities</h2>
      <p><strong>Pricing is the centerpiece.</strong> Charts below compare median and mean nightly prices (overall and by room type). Prices are missing for some cities; those markets are excluded from price computations.</p>
      <div class='row2' style='margin-top:10px;'>
        <div class='span7'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Median nightly price by city</h3>
          <svg id='chart_price_median' class='chart' viewBox='0 0 900 360' role='img' aria-label='Median price by city'></svg>
          <div class='muted' style='margin-top:8px; font-size:12px;'>Bars reflect <code>median(price)</code> using non-null prices only; labels show priced listing count.</div>
        </div>
        <div class='span5'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Mean nightly price by city</h3>
          <svg id='chart_price_mean' class='chart' viewBox='0 0 520 360' role='img' aria-label='Mean price by city'></svg>
          <div class='muted' style='margin-top:8px; font-size:12px;'>Means can be sensitive to extreme values; this dataset contains very large price outliers.</div>
        </div>
      </div>

      <h3 style='margin:14px 0 8px; font-size:14px; color:var(--muted);'>Median price by city and room type</h3>
      <svg id='chart_price_by_room' class='chart' viewBox='0 0 1100 430' role='img' aria-label='Median price by city and room type'></svg>
      <div class='legend'>
        <span><span class='swatch' style='background:#4da3ff'></span>Entire home/apt</span>
        <span><span class='swatch' style='background:#7c5cff'></span>Private room</span>
        <span><span class='swatch' style='background:#3ddc97'></span>Hotel room</span>
        <span><span class='swatch' style='background:#ffcc66'></span>Shared room</span>
      </div>

      <div class='callout' style='margin-top:12px;'>
        <strong>Data integrity note:</strong> Paris and Sydney have <code>price</code> missing for 100% of listings in this file. They are included in non-price metrics (supply, professionalization, availability, reviews), but excluded from all price medians/means.
      </div>
    </section>

    <section class='card' id='supply-structure'>
      <h2>Supply Structure & Host Concentration</h2>
      <p>This section focuses on commercialization signals: room-type composition and the share of listings controlled by multi-listing (“professional”) hosts, defined as <code>calculated_host_listings_count ≥ 5</code>.</p>

      <div class='row2' style='margin-top:10px;'>
        <div class='span7'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Professional host share by city</h3>
          <svg id='chart_prof_share' class='chart' viewBox='0 0 900 340' role='img' aria-label='Professional host share by city'></svg>
        </div>
        <div class='span5'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Entire-home share by city</h3>
          <svg id='chart_ent_share' class='chart' viewBox='0 0 520 340' role='img' aria-label='Entire home share by city'></svg>
        </div>
      </div>

      <p class='muted' style='margin-top:10px;'>Interpretation: higher professional-host share and higher entire-home share generally indicate a more commercialized market structure, which can correlate with tighter regulation and more institutional competition.</p>
    </section>

    <section class='card' id='guest-demand'>
      <h2>Guest Demand & Review Activity</h2>
      <p>Demand is proxied via <code>reviews_per_month</code>, <code>number_of_reviews</code>, and <code>number_of_reviews_ltm</code>. Review activity can vary by guest propensity to review and platform dynamics; treat as directional, not absolute occupancy.</p>

      <div class='row2' style='margin-top:10px;'>
        <div class='span7'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Average reviews per month by city</h3>
          <svg id='chart_rpm' class='chart' viewBox='0 0 900 340' role='img' aria-label='Average reviews per month by city'></svg>
        </div>
        <div class='span5'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Median recency of last review (days)</h3>
          <svg id='chart_recency' class='chart' viewBox='0 0 520 340' role='img' aria-label='Median recency of last review by city'></svg>
        </div>
      </div>

      <p class='muted' style='margin-top:10px;'>Recency is computed as <code>(scrape_date - median(last_review))</code> for listings with a non-null <code>last_review</code>.</p>
    </section>

    <section class='card' id='availability-minimumnights'>
      <h2>Availability & Booking Constraints</h2>
      <p>Availability (<code>availability_365</code>) reflects how open listings are over the next year. Minimum-night rules (<code>minimum_nights</code>) can indicate market norms or regulatory/operational constraints.</p>

      <div class='row2' style='margin-top:10px;'>
        <div class='span7'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Mean availability (days/year) by city</h3>
          <svg id='chart_avail' class='chart' viewBox='0 0 900 340' role='img' aria-label='Mean availability by city'></svg>
        </div>
        <div class='span5'>
          <h3 style='margin:0 0 8px; font-size:14px; color:var(--muted);'>Minimum nights (median & p90)</h3>
          <svg id='chart_min_nights' class='chart' viewBox='0 0 520 340' role='img' aria-label='Minimum nights by city'></svg>
        </div>
      </div>

      <div class='callout' style='margin-top:12px;'>
        <strong>Notable constraint signal:</strong> Paris shows an extreme right tail in <code>minimum_nights</code> (p90 and above at 365 nights), consistent with strong long-term-rental framing for a large portion of listings in this snapshot.
      </div>
    </section>

    <section class='card' id='key-takeaways'>
      <h2>Key Takeaways & Strategic Implications</h2>
      <p>Action-oriented implications aligned to pricing, professionalization, and demand proxies.</p>
      <ul>
        <li><strong>Pricing benchmarking:</strong> Use median price as the primary cross-market comparator; mean price can be distorted by outliers (especially visible in Bangkok).</li>
        <li><strong>Regulatory exposure proxy:</strong> Cities with high professional-host share (≥5 listings) may face more regulatory scrutiny and institutional competition.</li>
        <li><strong>Commercialization via room mix:</strong> Very high entire-home share suggests more investor-style supply; pair with availability for a clearer commercialization read.</li>
        <li><strong>Demand screening:</strong> Combine reviews/month with last-review recency to prioritize markets with both high velocity and recent activity.</li>
        <li><strong>Constraint-driven strategy:</strong> High minimum-night requirements can shift feasible strategies from short-stay tourism toward mid/long-stay positioning.</li>
      </ul>
      <footer>
        <div>Method: All KPIs computed from <code>benchmark/data.csv</code> with missing values excluded only where mathematically required (e.g., missing prices).</div>
      </footer>
    </section>
  </div>
</div>

<script>
  const DATA = {data_json};

  function $(id) {{ return document.getElementById(id); }}

  function niceMax(x) {{
    if (!isFinite(x) || x <= 0) return 1;
    const pow = Math.pow(10, Math.floor(Math.log10(x)));
    const n = x / pow;
    const m = n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10;
    return m * pow;
  }}

  function barChart(svg, items, opts) {{
    const W = svg.viewBox.baseVal.width, H = svg.viewBox.baseVal.height;
    const pad = {{l: 130, r: 20, t: 18, b: 40}};
    const innerW = W - pad.l - pad.r;
    const innerH = H - pad.t - pad.b;

    const maxV = Math.max(0, ...items.map(d => d.value || 0));
    const yMax = niceMax(maxV * 1.05);

    while (svg.firstChild) svg.removeChild(svg.firstChild);

    const gridN = 5;
    for (let i=0;i<=gridN;i++) {{
      const y = pad.t + innerH - (i/gridN)*innerH;
      const line = document.createElementNS('http://www.w3.org/2000/svg','line');
      line.setAttribute('x1', pad.l);
      line.setAttribute('x2', pad.l + innerW);
      line.setAttribute('y1', y);
      line.setAttribute('y2', y);
      line.setAttribute('stroke', 'rgba(31,43,69,0.9)');
      line.setAttribute('stroke-width','1');
      svg.appendChild(line);

      const txt = document.createElementNS('http://www.w3.org/2000/svg','text');
      txt.setAttribute('x', pad.l - 8);
      txt.setAttribute('y', y + 4);
      txt.setAttribute('text-anchor','end');
      txt.setAttribute('fill','rgba(159,176,208,0.95)');
      txt.setAttribute('font-size','11');
      const v = (i/gridN)*yMax;
      txt.textContent = opts.tickFmt ? opts.tickFmt(v) : Math.round(v).toString();
      svg.appendChild(txt);
    }}

    const n = items.length;
    const barH = innerH / n;
    const barPad = 6;

    items.forEach((d, idx) => {{
      const y0 = pad.t + idx*barH + barPad;
      const h = barH - barPad*2;
      const v = d.value || 0;
      const w = (v / yMax) * innerW;

      const label = document.createElementNS('http://www.w3.org/2000/svg','text');
      label.setAttribute('x', pad.l - 10);
      label.setAttribute('y', y0 + h/2 + 4);
      label.setAttribute('text-anchor','end');
      label.setAttribute('fill','#eaf0ff');
      label.setAttribute('font-size','12');
      label.textContent = d.label;
      svg.appendChild(label);

      const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
      rect.setAttribute('x', pad.l);
      rect.setAttribute('y', y0);
      rect.setAttribute('width', Math.max(0,w));
      rect.setAttribute('height', h);
      rect.setAttribute('rx', 6);
      rect.setAttribute('fill', d.color || 'rgba(77,163,255,0.9)');
      rect.setAttribute('stroke', 'rgba(32,48,83,0.8)');
      rect.setAttribute('stroke-width','1');
      svg.appendChild(rect);

      const val = document.createElementNS('http://www.w3.org/2000/svg','text');
      val.setAttribute('x', pad.l + Math.max(0,w) + 8);
      val.setAttribute('y', y0 + h/2 + 4);
      val.setAttribute('fill','rgba(234,240,255,0.95)');
      val.setAttribute('font-size','12');
      val.setAttribute('font-family','ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace');
      val.textContent = (opts.valueFmt ? opts.valueFmt(v, d) : v.toString()) + (d.note ? `  (${d.note})` : '');
      svg.appendChild(val);
    }});
  }}

  function stacked100(svg, rows, categories, opts) {{
    const W = svg.viewBox.baseVal.width, H = svg.viewBox.baseVal.height;
    const pad = {{l: 120, r: 20, t: 18, b: 20}};
    const innerW = W - pad.l - pad.r;
    const innerH = H - pad.t - pad.b;

    while (svg.firstChild) svg.removeChild(svg.firstChild);

    const n = rows.length;
    const rowH = innerH / n;
    const barPad = 6;

    for (let p=0;p<=100;p+=20) {{
      const x = pad.l + (p/100)*innerW;
      const line = document.createElementNS('http://www.w3.org/2000/svg','line');
      line.setAttribute('x1', x);
      line.setAttribute('x2', x);
      line.setAttribute('y1', pad.t);
      line.setAttribute('y2', pad.t+innerH);
      line.setAttribute('stroke', 'rgba(31,43,69,0.7)');
      line.setAttribute('stroke-width','1');
      svg.appendChild(line);

      const txt = document.createElementNS('http://www.w3.org/2000/svg','text');
      txt.setAttribute('x', x);
      txt.setAttribute('y', pad.t+innerH+16);
      txt.setAttribute('text-anchor','middle');
      txt.setAttribute('fill','rgba(159,176,208,0.95)');
      txt.setAttribute('font-size','11');
      txt.textContent = p + '%';
      svg.appendChild(txt);
    }}

    rows.forEach((r, idx) => {{
      const y0 = pad.t + idx*rowH + barPad;
      const h = rowH - barPad*2;

      const label = document.createElementNS('http://www.w3.org/2000/svg','text');
      label.setAttribute('x', pad.l - 10);
      label.setAttribute('y', y0 + h/2 + 4);
      label.setAttribute('text-anchor','end');
      label.setAttribute('fill','#eaf0ff');
      label.setAttribute('font-size','12');
      label.textContent = r.label;
      svg.appendChild(label);

      let acc = 0;
      categories.forEach(cat => {{
        const v = r.values[cat] || 0;
        const x = pad.l + (acc/100)*innerW;
        const w = (v/100)*innerW;
        const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
        rect.setAttribute('x', x);
        rect.setAttribute('y', y0);
        rect.setAttribute('width', Math.max(0,w));
        rect.setAttribute('height', h);
        rect.setAttribute('fill', (opts.colors && opts.colors[cat]) || 'rgba(77,163,255,0.9)');
        rect.setAttribute('stroke', 'rgba(0,0,0,0)');
        svg.appendChild(rect);
        acc += v;
      }});

      const outline = document.createElementNS('http://www.w3.org/2000/svg','rect');
      outline.setAttribute('x', pad.l);
      outline.setAttribute('y', y0);
      outline.setAttribute('width', innerW);
      outline.setAttribute('height', h);
      outline.setAttribute('rx', 6);
      outline.setAttribute('fill', 'none');
      outline.setAttribute('stroke', 'rgba(32,48,83,0.8)');
      outline.setAttribute('stroke-width','1');
      svg.appendChild(outline);
    }});
  }}

  const perCity = DATA.per_city.slice();

  const listingsItems = perCity.slice().sort((a,b)=>b.listings-a.listings)
    .map(d=>({{label:d.city, value:d.listings, note: null, color:'rgba(77,163,255,0.9)'}}));
  barChart($('chart_listings'), listingsItems, {{ tickFmt:(v)=>Math.round(v).toLocaleString(), valueFmt:(v)=>Math.round(v).toLocaleString() }});

  const mixRows = [];
  const mix = DATA.room_mix;
  const cats = ['Entire home/apt','Private room','Hotel room','Shared room'];
  const colors = {{
    'Entire home/apt':'#4da3ff',
    'Private room':'#7c5cff',
    'Hotel room':'#3ddc97',
    'Shared room':'#ffcc66'
  }};
  const cities = [...new Set(mix.map(d=>d.city))];
  cities.sort((a,b)=>{{
    const la = (perCity.find(x=>x.city===a) || {{}}).listings || 0;
    const lb = (perCity.find(x=>x.city===b) || {{}}).listings || 0;
    return lb-la;
  }});
  cities.forEach(city=>{{
    const values={{}};
    mix.filter(d=>d.city===city).forEach(d=>values[d.room_type]=d.share);
    mixRows.push({{label:city, values}});
  }});
  stacked100($('chart_room_mix'), mixRows, cats, {{colors}});

  const priceCities = perCity.filter(d=>d.price_n>0);
  const medianItems = priceCities.slice().sort((a,b)=>b.price_median-a.price_median)
    .map(d=>({{label:d.city, value:d.price_median, note:`n=${{Math.round(d.price_n).toLocaleString()}}`, color:'rgba(124,92,255,0.9)'}}));
  barChart($('chart_price_median'), medianItems, {{ tickFmt:(v)=>'$'+Math.round(v).toLocaleString(), valueFmt:(v)=>'$'+Math.round(v).toLocaleString() }});

  const meanItems = priceCities.slice().sort((a,b)=>b.price_mean-a.price_mean)
    .map(d=>({{label:d.city, value:d.price_mean, note:`n=${{Math.round(d.price_n).toLocaleString()}}`, color:'rgba(77,163,255,0.9)'}}));
  barChart($('chart_price_mean'), meanItems, {{ tickFmt:(v)=>'$'+Math.round(v).toLocaleString(), valueFmt:(v)=>'$'+Math.round(v).toLocaleString() }});

  (function(){{
    const svg=$('chart_price_by_room');
    const W=svg.viewBox.baseVal.width, H=svg.viewBox.baseVal.height;
    const pad={{l:110,r:20,t:18,b:110}};
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    const rows=DATA.pricing_by_room_type;
    const cities=[...new Set(rows.map(d=>d.city))].filter(c=>priceCities.some(p=>p.city===c));
    cities.sort((a,b)=>{{
      const ma = (priceCities.find(x=>x.city===a) || {{}}).price_median || 0;
      const mb = (priceCities.find(x=>x.city===b) || {{}}).price_median || 0;
      return mb-ma;
    }});
    const roomTypes=['Entire home/apt','Private room','Hotel room','Shared room'];

    const maxV=Math.max(...rows.map(d=>d.price_median||0));
    const yMax=niceMax(maxV*1.05);
    const innerW=W-pad.l-pad.r;
    const innerH=H-pad.t-pad.b;

    const gridN=5;
    for(let i=0;i<=gridN;i++){{
      const y=pad.t+innerH-(i/gridN)*innerH;
      const line=document.createElementNS('http://www.w3.org/2000/svg','line');
      line.setAttribute('x1',pad.l);
      line.setAttribute('x2',pad.l+innerW);
      line.setAttribute('y1',y);
      line.setAttribute('y2',y);
      line.setAttribute('stroke','rgba(31,43,69,0.9)');
      line.setAttribute('stroke-width','1');
      svg.appendChild(line);
      const txt=document.createElementNS('http://www.w3.org/2000/svg','text');
      txt.setAttribute('x',pad.l-8);
      txt.setAttribute('y',y+4);
      txt.setAttribute('text-anchor','end');
      txt.setAttribute('fill','rgba(159,176,208,0.95)');
      txt.setAttribute('font-size','11');
      const v=(i/gridN)*yMax;
      txt.textContent='$'+Math.round(v).toLocaleString();
      svg.appendChild(txt);
    }}

    const nCities=cities.length;
    const groupW=innerW/nCities;
    const barW=Math.min(22, (groupW-18)/roomTypes.length);

    cities.forEach((city, idx)=>{{
      const x0=pad.l+idx*groupW+9;
      const lbl=document.createElementNS('http://www.w3.org/2000/svg','text');
      lbl.setAttribute('x', x0 + (roomTypes.length*barW)/2 );
      lbl.setAttribute('y', pad.t+innerH+22);
      lbl.setAttribute('text-anchor','middle');
      lbl.setAttribute('fill','#eaf0ff');
      lbl.setAttribute('font-size','12');
      lbl.setAttribute('transform',`rotate(30 ${{x0 + (roomTypes.length*barW)/2}} ${{pad.t+innerH+22}})`);
      lbl.textContent=city;
      svg.appendChild(lbl);

      roomTypes.forEach((rt, j)=>{{
        const row=rows.find(d=>d.city===city && d.room_type===rt);
        if(!row) return;
        const v=row.price_median;
        const h=(v/yMax)*innerH;
        const x=x0 + j*barW;
        const y=pad.t+innerH-h;
        const rect=document.createElementNS('http://www.w3.org/2000/svg','rect');
        rect.setAttribute('x',x);
        rect.setAttribute('y',y);
        rect.setAttribute('width',barW-2);
        rect.setAttribute('height',Math.max(0,h));
        rect.setAttribute('fill', colors[rt]);
        rect.setAttribute('rx','4');
        svg.appendChild(rect);
      }});
    }});
  }})();

  const profItems = perCity.slice().sort((a,b)=>b.professional_share-a.professional_share)
    .map(d=>({{label:d.city, value:d.professional_share, note:null, color:'rgba(61,220,151,0.9)'}}));
  barChart($('chart_prof_share'), profItems, {{ tickFmt:(v)=>Math.round(v)+'%', valueFmt:(v)=>v.toFixed(1)+'%' }});

  const entItems = perCity.slice().sort((a,b)=>b.entire_home_share-a.entire_home_share)
    .map(d=>({{label:d.city, value:d.entire_home_share, note:null, color:'rgba(77,163,255,0.9)'}}));
  barChart($('chart_ent_share'), entItems, {{ tickFmt:(v)=>Math.round(v)+'%', valueFmt:(v)=>v.toFixed(1)+'%' }});

  const rpmItems = perCity.slice().sort((a,b)=>(b.reviews_per_month_mean||0)-(a.reviews_per_month_mean||0))
    .map(d=>({{label:d.city, value:(d.reviews_per_month_mean||0), note:null, color:'rgba(255,204,102,0.9)'}}));
  barChart($('chart_rpm'), rpmItems, {{ tickFmt:(v)=>v.toFixed(1), valueFmt:(v)=>v.toFixed(2) }});

  const recItems = perCity.slice().filter(d=>isFinite(d.median_recency_days))
    .sort((a,b)=>a.median_recency_days-b.median_recency_days)
