# Load inputs
req=json.load(open('benchmark/task_input.json'))
df=pd.read_csv('benchmark/data.csv')
df['last_review_dt']=pd.to_datetime(df['last_review'], errors='coerce')
scrape=pd.to_datetime(df['scrape_date'].dropna().iloc[0]) if df['scrape_date'].notna().any() else pd.NaT

cities_expected=["New York","London","Paris","Tokyo","Barcelona","Los Angeles","Amsterdam","Bangkok","Rome","Sydney"]
cities_present=sorted(df['city'].dropna().unique())
missing_expected=sorted(set(cities_expected)-set(cities_present))

# per-city KPIs
pc=(df.groupby('city')
      .agg(listings=('id','size'),
           price_n=('price', lambda s: s.notna().sum()),
           price_missing_share=('price', lambda s: s.isna().mean()*100),
           price_median=('price','median'),
           price_mean=('price','mean'),
           professional_share=('calculated_host_listings_count', lambda s: (s>=5).mean()*100),
           entire_home_share=('room_type', lambda s: (s=='Entire home/apt').mean()*100),
           reviews_per_month_mean=('reviews_per_month','mean'),
           availability_365_mean=('availability_365','mean'),
           minimum_nights_median=('minimum_nights','median'),
           minimum_nights_p90=('minimum_nights', lambda s: s.quantile(0.90)),
          )
      .reset_index())
recency=(df.groupby('city')['last_review_dt'].apply(lambda s: s.dropna().median()).reset_index(name='last_review_median'))
pc=pc.merge(recency, on='city', how='left')
pc['median_recency_days']=pc['last_review_median'].apply(lambda d: (scrape-d).days if pd.notna(d) and pd.notna(scrape) else np.nan)

