pr=(df.dropna(subset=['price'])
      .groupby(['city','room_type'])
      .agg(price_median=('price','median'), price_mean=('price','mean'), n=('price','size'))
      .reset_index())

# room mix
mix=df.groupby(['city','room_type']).size().reset_index(name='count')
mix['share']=mix.groupby('city')['count'].transform(lambda x: x/x.sum()*100)

# payload
payload={
