def fmt_num(x, decimals=0):
    if x is None or (isinstance(x,float) and np.isnan(x)):
        return '—'
    return f"{x:,.{decimals}f}" if decimals else f"{x:,.0f}"

def fmt_pct(x, decimals=1):
    if x is None or (isinstance(x,float) and np.isnan(x)):
        return '—'
    return f"{x:.{decimals}f}%"

def fmt_money(x, decimals=0):
    if x is None or (isinstance(x,float) and np.isnan(x)):
        return '—'
    return f"${x:,.{decimals}f}"

def fmt_date(d):
    if pd.isna(d):
