        fmt_money(r['price_median'],0),
        fmt_money(r['price_mean'],0),
        fmt_pct(r['professional_share'],1),
        fmt_pct(r['entire_home_share'],1),
        fmt_num(r['reviews_per_month_mean'],2),
        fmt_num(r['availability_365_mean'],0),
        fmt_num(r['minimum_nights_median'],0),
        fmt_date(r['last_review_median']),
    ])
header=''.join(f"<th>{c[0]}</th>" for c in cols)
body='\n'.join('<tr>'+''.join(f"<td>{cell}</td>" for cell in row)+'</tr>' for row in rows)
table_html=f"<table class='tbl'><thead><tr>{header}</tr></thead><tbody>{body}</tbody></table>"

# key takeaways
def kt_list():
    kt=[]
    pc_price=pc[pc['price_n']>0].copy()
    if not pc_price.empty:
        leader=pc_price.sort_values('price_median', ascending=False).iloc[0]
        laggard=pc_price.sort_values('price_median', ascending=True).iloc[0]
        no_price=pc[pc['price_n']==0]['city'].tolist()
        note_no_price = f" Pricing metrics are unavailable for {', '.join(no_price)} due to 100% missing `price`." if no_price else ''
        kt.append(f"Pricing spread: {leader.city} has the highest median nightly price ({fmt_money(leader.price_median,0)}; n={fmt_num(leader.price_n)} priced listings) while {laggard.city} is the lowest among cities with price data ({fmt_money(laggard.price_median,0)}).{note_no_price}")
    else:
        kt.append("Pricing metrics cannot be computed because `price` is missing for all cities in the provided dataset.")

    prof_leader=pc.sort_values('professional_share', ascending=False).iloc[0]
    prof_laggard=pc.sort_values('professional_share', ascending=True).iloc[0]
    kt.append(f"Professionalization: {prof_leader.city} shows the highest professional-host share ({fmt_pct(prof_leader.professional_share,1)} of listings have `calculated_host_listings_count` ≥ 5), versus {prof_laggard.city} at {fmt_pct(prof_laggard.professional_share,1)}.")

    ent_leader=pc.sort_values('entire_home_share', ascending=False).iloc[0]
    ent_laggard=pc.sort_values('entire_home_share', ascending=True).iloc[0]
    kt.append(f"Commercial listing mix: Entire-home supply is most dominant in {ent_leader.city} ({fmt_pct(ent_leader.entire_home_share,1)} of listings) and least dominant in {ent_laggard.city} ({fmt_pct(ent_laggard.entire_home_share,1)}).")

    rpm_leader=pc.sort_values('reviews_per_month_mean', ascending=False).iloc[0]
    kt.append(f"Demand proxy: {rpm_leader.city} leads on average `reviews_per_month` ({fmt_num(rpm_leader.reviews_per_month_mean,2)}), suggesting comparatively higher booking velocity (subject to review-rate differences).")

    avail_leader=pc.sort_values('availability_365_mean', ascending=False).iloc[0]
    minn_high=pc.sort_values('minimum_nights_p90', ascending=False).iloc[0]
    kt.append(f"Access & constraints: {avail_leader.city} has the highest mean availability ({fmt_num(avail_leader.availability_365_mean,0)} days/year). Minimum-night constraints are most pronounced in {minn_high.city} (p90={fmt_num(minn_high.minimum_nights_p90,0)} nights; median={fmt_num(minn_high.minimum_nights_median,0)}).")

    return kt

kt_html=''.join(f"<li><strong>{i+1}.</strong> {t}</li>" for i,t in enumerate(kt_list()))

html=build_html(
