    scrape.date().isoformat() if pd.notna(scrape) else '—',
    df.shape[0],
    float(df['price'].isna().mean()*100),
    table_html
)

Path('output').mkdir(exist_ok=True)
Path('output/final_report.html').write_text(html, encoding='utf-8')
print('Wrote output/final_report.html')
